class SegmentTree:

    def __init__(self, nums):
        self.n = len(nums)
        self.tree = [0] * 4 * self.n
        self.buildTree(nums, 0, self.n - 1, 0)

    def buildTree(self, nums, left, right, idx):
        if left == right:
            self.tree[idx] = nums[left]
            return
        mid = (left + right) // 2
        self.buildTree(nums, left, mid, 2*idx + 1)
        self.buildTree(nums, mid + 1, right, 2*idx + 2)
        self.tree[idx] = self.tree[2 * idx + 1] + self.tree[2 * idx + 2]

    def update(self, left, right, idx, pos, val):
        if left == right:
            self.tree[idx] = val
            return

        mid = (left + right) // 2
        if pos <= mid:
            self.update(left, mid, 2 * idx + 1, pos, val)
        else:
            self.update(mid + 1, right, 2 * idx + 2, pos, val)
        self.tree[idx] = self.tree[2 * idx + 1] + self.tree[2 * idx + 2]

    def query(self, left, right, idx, qLeft, qRight):
        # out of range
        if qRight < left or qLeft > right:
            return 0

        if qLeft <= left and right <= qRight:
            return self.tree[idx]

        mid = (left + right) // 2
        resLeft = self.query(left, mid, 2*idx + 1, qLeft, qRight)
        resRight = self.query(mid + 1, right, 2*idx + 2, qLeft, qRight)
        return resLeft + resRight

class NumArray:

    def __init__(self, nums: list[int]):
        self.tree = SegmentTree(nums)

    def update(self, index: int, val: int) -> None:
        self.tree.update(0, self.tree.n - 1, 0, index, val)

    def sumRange(self, left: int, right: int) -> int:
        return self.tree.query(0, self.tree.n - 1, 0, left, right)


